import json
data = json.load(open('/app/resources/treasury_bulletin_2000_09.json'))

# Check all keys at different levels
def explore(obj, path=""):
    if isinstance(obj, dict):
        for k, v in obj.items():
            explore(v, f"{path}.{k}")
    elif isinstance(obj, list):
        for i, v in enumerate(obj[:5]):  # Only first 5
            explore(v, f"{path}[{i}]")

# Search for anything with debt, sustain, indicator, growth
for elem in data['document']['elements']:
    text = str(elem)
    if any(x in text.lower() for x in ['sustain', 'indicator', 'variation', 'coefficient']):
        print(elem)
        print("---")
        break
